 if(style===1||style===5||style===17){const y=style===5?h-edge:edge;path([[edge,y],[w*.3,y+edge*.35],[w*.7,y+edge*.35],[w-edge,y]]);for(let i=0;i<7;i++)at(i,edge+(w-edge*2)*i/6,y+Math.sin(i/6*Math.PI)*edge*(style===17?1.3:.35),style===17?.95:.7);}
 if(style===2||style===11||style===16){for(let i=0;i<8;i++){at(style===16?2:i,edge,edge+(h-edge*2)*i/7,style===11?.85:.65,style===11?i*.5:-.15);at(style===16?2:i+1,w-edge,edge+(h-edge*2)*i/7,style===16?.9:.65,style===11?-i*.5:.15);}}
 if(style===3){ctx.fillStyle=soft;ctx.globalAlpha=.65;ctx.fillRect(20,h-edge*1.8,w-40,edge*1.1);ctx.globalAlpha=1;for(let i=0;i<5;i++)at(i,w*.2+w*.15*i,h-edge*1.25,.9);}
 if(style===15){path([[w-edge,edge],[w-edge,h-edge]]);for(let i=0;i<5;i++)at(i,w-edge,h*.2+h*.15*i,1,i*.1);}
 if(style===4||style===9||style===14){for(let i=0;i<18;i++){const x=edge+(w-2*edge)*((i*7%19)/18),y=i%2?edge*.9:h-edge*.9;at(style===14?3:i,x,y,.4+(i%3)*.12,i*.4);if(style===9){ctx.fillStyle=accent;ctx.fillRect(x+8,y+9,3,5);}}}
 if(style===6||style===13||style===18){for(let i=0;i<(style===18?3:1);i++){const x=style===13?edge*1.7:w-edge*1.45-i*s*1.8,y=style===13?edge*1.8:h-edge*1.4;ctx.strokeStyle=accent;ctx.fillStyle=soft;ctx.beginPath();ctx.arc(x,y,s*.8,0,Math.PI*2);ctx.fill();ctx.stroke();at(i,x,y,1);}}
